{
  "replaceAll": true,
  "chunking": {
    "chunkSize": 900,
    "overlap": 120
  },
  "documents": [
    {
      "title": "Orion Account Security Policy",
      "tags": ["security", "auth"],
      "content": "Users can reset passwords through verified email. After 5 failed login attempts, account lockout is activated."
    },
    {
      "title": "Workspace Roles and Permissions",
      "tags": ["workspace", "roles"],
      "content": "Owner can transfer ownership. Admin manages members and settings. Member can create and update tasks."
    }
  ]
}

{
  "topK": 5,
  "retrievalConfig": {
    "candidateLimit": 1200,
    "minScore": -1,
    "deduplicateByDocument": false
  },
  "samples": [
    {
      "query": "How do I reset my Orion account password?",
      "expectedKeywords": ["password", "reset", "verification"]
    },
    {
      "query": "How to invite a new member to workspace?",
      "expectedKeywords": ["invite", "workspace", "member"]
    }
  ]
}

{
  "configs": [
    { "chunkSize": 600, "overlap": 80 },
